package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;
import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import org.junit.jupiter.api.*;
import java.time.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;

@SpringBootTest(properties="greenocean.clinic.commerce-enabled=true") @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseP2Test extends PhaseO3Fixtures {
 @Autowired ClinicCommerce commerce;@Autowired ProfessionalScheduling scheduling;@Autowired ProfessionalWorkflowService legacy;
 UUID policy,slot;
 @BeforeEach void clinic(){PhasePFixtures.qualified(db,author.id(),issuer.id());policy=commerce.policy(issuer.id(),new ClinicCommerce.Policy("synthetic-"+UUID.randomUUID(),1000,0,"Synthetic explicit commission agreement","Synthetic cancellation review and no-show refund terms"));slot=scheduling.slot(author.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(7200),Instant.now().plusSeconds(9000),"TEXT",0,"Asia/Tehran",true));commerce.offer(author.id(),slot,policy,false);}
 ClinicCommerce.Booking booking(){return new ClinicCommerce.Booking(slot,UUID.randomUUID(),2,policy,0,true);}
 @Test void freeDirectBookingSnapshotsTermsAndRetriesOnce(){var in=booking();var saved=commerce.book(learner.id(),in);UUID id=(UUID)saved.get("id");assertThat(saved.get("status")).isEqualTo("CONFIRMED");assertThat(commerce.book(learner.id(),in).get("id")).isEqualTo(id);assertThat(db.queryForObject("SELECT count(*) FROM clinic_invoices WHERE appointment_id=?",Integer.class,id)).isEqualTo(1);assertThat(commerce.finances(learner.id(),false).toString()).contains("IRR").doesNotContain("available to spend");}
 @Test void foreignAccessAndSecondPatientCannotReserve(){UUID id=(UUID)commerce.book(learner.id(),booking()).get("id");assertThatThrownBy(()->commerce.book(other.id(),booking())).isInstanceOf(ConflictException.class);assertThatThrownBy(()->commerce.appointment(other.id(),id)).isInstanceOf(NotFoundException.class);}
 @Test void stalePriceAndImplicitConfirmationRejected(){assertThatThrownBy(()->commerce.book(learner.id(),new ClinicCommerce.Booking(slot,UUID.randomUUID(),1,policy,0,true))).isInstanceOf(ConflictException.class);assertThatThrownBy(()->commerce.book(learner.id(),new ClinicCommerce.Booking(slot,UUID.randomUUID(),2,policy,100,true))).isInstanceOf(ConflictException.class);assertThatThrownBy(()->commerce.book(learner.id(),new ClinicCommerce.Booking(slot,UUID.randomUUID(),2,policy,0,false))).isInstanceOf(ConflictException.class);}
 @Test void noPaidBookingWithoutRealAuthorizedProvider(){db.update("UPDATE professional_availability_slots SET price_units=10000 WHERE id=?",slot);assertThatThrownBy(()->commerce.book(learner.id(),new ClinicCommerce.Booking(slot,UUID.randomUUID(),2,policy,10000,true))).isInstanceOf(ConflictException.class);assertThat(db.queryForObject("SELECT status FROM professional_availability_slots WHERE id=?",String.class,slot)).isEqualTo("AVAILABLE");}
 @Test void cancellationNeverReopensReservedSlotAndLegacyCannotComplete(){UUID id=(UUID)commerce.book(learner.id(),booking()).get("id");assertThatThrownBy(()->legacy.updateConsultationStatus(id,author.id(),new com.greenocean.backend.professional.dto.UpdateConsultationStatusRequest("COMPLETED"))).isInstanceOf(NotFoundException.class);commerce.change(learner.id(),id,new ClinicCommerce.Change(1,"CANCEL","Patient cancelled voluntarily"));commerce.change(learner.id(),id,new ClinicCommerce.Change(1,"CANCEL","Retry of patient cancellation"));assertThat(db.queryForObject("SELECT status FROM professional_availability_slots WHERE id=?",String.class,slot)).isEqualTo("CANCELLED");}
 @Test void exceptionalApprovalIsExplicitAndIndependentOfPayment(){commerce.offer(author.id(),slot,policy,true);var in=new ClinicCommerce.Booking(slot,UUID.randomUUID(),3,policy,0,true);UUID id=(UUID)commerce.book(learner.id(),in).get("id");assertThat(commerce.appointment(learner.id(),id).get("status")).isEqualTo("REQUESTED");assertThatThrownBy(()->commerce.change(learner.id(),id,new ClinicCommerce.Change(1,"APPROVE","Patient attempting approval"))).isInstanceOf(ConflictException.class);commerce.change(author.id(),id,new ClinicCommerce.Change(1,"APPROVE","Professional explicitly accepted request"));assertThat(commerce.appointment(learner.id(),id).get("status")).isEqualTo("CONFIRMED");}
 @Test void noShowCannotBeInferredFromEarlyOrMissingClientHeartbeat(){UUID id=(UUID)commerce.book(learner.id(),booking()).get("id");assertThatThrownBy(()->commerce.noShow(issuer.id(),id,"Synthetic staff review with no elapsed deadline",true)).isInstanceOf(ConflictException.class);assertThatThrownBy(()->commerce.noShow(learner.id(),id,"Synthetic unauthorized no-show decision",true)).isInstanceOf(ForbiddenException.class);}
 @Test void currentQualificationRequiredAtBooking(){db.update("UPDATE professional_verifications SET qualification_state='SUSPENDED' WHERE professional_user_id=?",author.id());assertThatThrownBy(()->commerce.book(learner.id(),booking())).isInstanceOf(ForbiddenException.class);}
 @Test void rawPaymentsOrSelfDeclaredSubscriptionCannotBuyAuthorization(){assertThatThrownBy(()->commerce.plan(issuer.id(),"bad-plan",List.of("CLINICAL_AUTHORIZATION"),100,30)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->commerce.policy(learner.id(),new ClinicCommerce.Policy("bad",0,0,"Long enough terms","Long enough refund policy"))).isInstanceOf(ForbiddenException.class);}
 @Test void ownFinancialWorkspaceContainsNoOtherPatientOrClinicalNotes(){commerce.book(learner.id(),booking());assertThat(commerce.finances(other.id(),false).get("appointments")).asList().isEmpty();assertThat(commerce.finances(author.id(),true).toString()).doesNotContain("note=","email=","license_identifier");}
 @Test void freeAdministrativeSubscriptionIsExplicitBoundedAndNeverChangesQualification(){UUID plan=commerce.plan(issuer.id(),"qa-plan-"+UUID.randomUUID(),List.of("ADMIN_REPORTS"),0,7);UUID key=UUID.randomUUID();assertThatThrownBy(()->commerce.subscribe(author.id(),plan,key,false)).isInstanceOf(ConflictException.class);var order=commerce.subscribe(author.id(),plan,key,true);assertThat(order.get("state")).isEqualTo("ACTIVE");assertThat(commerce.subscribe(author.id(),plan,key,true).get("id")).isEqualTo(order.get("id"));assertThat(commerce.subscriptions(author.id())).hasSize(1);assertThat(db.queryForObject("SELECT count(*) FROM clinic_professional_subscriptions WHERE order_id=?",Integer.class,order.get("id"))).isEqualTo(1);}
 @Test void communityModeratorHasNoFinancialOperationsAuthority(){assertThatThrownBy(()->commerce.operations(reviewer.id())).isInstanceOf(ForbiddenException.class);}
}
